-- Keep the Ras Sedr contact directory independent of activity and loading status.
-- The branch snapshot is read-only; all driver records belonging to the branch are listed.
create or replace function public.branch_get_snapshot()
returns jsonb language plpgsql security definer
set search_path to 'pg_catalog','public'
as $function$
declare v_actor uuid; v_office public.offices%rowtype;
begin
 v_actor:=public.current_ras_sedr_branch_user();
 select * into v_office from public.offices where office_code='RAS_SEDR' and office_type='BRANCH' and is_active=true;
 if not found then raise exception 'BRANCH_OFFICE_INACTIVE'; end if;
 return jsonb_build_object(
 'office',jsonb_build_object('office_id',v_office.office_id,'office_code',v_office.office_code,'name',v_office.name,'latitude',v_office.latitude,'longitude',v_office.longitude,'geofence_radius_m',v_office.geofence_radius_m),
 'available_loads',coalesce((select jsonb_agg(jsonb_build_object('load_order_id',lo.load_order_id,'order_number',lo.order_number,'factory_id',f.factory_id,'factory_name',f.name,'quarry_id',q.quarry_id,'quarry_name',q.name,'requested_quantity',lo.requested_quantity,'committed_quantity',coalesce(x.committed_quantity,0),'priority',lo.priority,'status',lo.status,'created_at',lo.created_at,'published_at',lo.published_at,'notes',lo.notes) order by lo.priority asc,lo.created_at asc) from public.load_orders lo join public.factories f on f.factory_id=lo.factory_id join public.quarries q on q.quarry_id=lo.quarry_id left join lateral (select count(*)::integer committed_quantity from public.bookings b where b.load_order_id=lo.load_order_id and b.status<>'CANCELLED') x on true where lo.status in ('PUBLISHED','IN_PROGRESS') and not exists(select 1 from public.bookings pending where pending.load_order_id=lo.load_order_id and pending.assignment_type='DIRECT' and pending.direct_acceptance_status='PENDING' and pending.status='ASSIGNED')),'[]'::jsonb),
 'allocations',coalesce((select jsonb_agg(jsonb_build_object('booking_id',b.booking_id,'load_order_id',b.load_order_id,'order_number',lo.order_number,'driver_id',d.driver_id,'driver_name',d.name,'driver_code',d.driver_code,'driver_phone',d.phone,'vehicle_id',v.vehicle_id,'plate_number',v.plate_number,'vehicle_code',v.vehicle_code,'factory_name',f.name,'quarry_name',q.name,'trip_code',b.trip_code,'status',b.status,'assignment_type',b.assignment_type,'assigned_at',b.assigned_at,'arrived_at',b.arrived_at) order by b.assigned_at desc) from public.bookings b join public.drivers d on d.driver_id=b.driver_id join public.vehicles v on v.vehicle_id=b.vehicle_id join public.load_orders lo on lo.load_order_id=b.load_order_id join public.factories f on f.factory_id=lo.factory_id join public.quarries q on q.quarry_id=lo.quarry_id where d.office_id=v_office.office_id and v.office_id=v_office.office_id and not (b.assignment_type='DIRECT' and b.direct_acceptance_status='PENDING' and b.status='ASSIGNED')),'[]'::jsonb),
 'actual_loading_records',coalesce((select jsonb_agg(jsonb_build_object('actual_load_id',al.actual_load_id,'booking_id',al.booking_id,'actual_weight',al.actual_weight,'ticket_number',al.ticket_number,'loaded_at',al.loaded_at,'notes',al.notes,'driver_name',d.name,'plate_number',v.plate_number,'factory_name',f.name,'quarry_name',q.name,'trip_code',b.trip_code,'order_number',lo.order_number) order by al.loaded_at desc) from public.actual_loading_records al join public.bookings b on b.booking_id=al.booking_id join public.drivers d on d.driver_id=b.driver_id join public.vehicles v on v.vehicle_id=b.vehicle_id join public.load_orders lo on lo.load_order_id=b.load_order_id join public.factories f on f.factory_id=lo.factory_id join public.quarries q on q.quarry_id=lo.quarry_id where d.office_id=v_office.office_id and v.office_id=v_office.office_id),'[]'::jsonb),
 'waiting_list','[]'::jsonb,
 'directory',coalesce((select jsonb_agg(jsonb_build_object('driver_id',d.driver_id,'driver_code',d.driver_code,'driver_name',d.name,'driver_phone',d.phone,'driver_is_active',d.is_active,'vehicle_id',v.vehicle_id,'plate_number',v.plate_number,'vehicle_code',v.vehicle_code,'vehicle_is_active',v.is_active,'owner_name',o.name,'owner_phone',o.phone) order by d.name nulls last,d.driver_code) from public.drivers d left join lateral (select a.vehicle_id from public.driver_vehicle_assignments a where a.driver_id=d.driver_id and a.ended_at is null order by a.assigned_at desc limit 1) current_assignment on true left join public.vehicles v on v.vehicle_id=current_assignment.vehicle_id and v.office_id=v_office.office_id left join public.vehicle_owners o on o.owner_id=v.owner_id where d.office_id=v_office.office_id),'[]'::jsonb),
 'office_notifications',coalesce((select jsonb_agg(jsonb_build_object('id',n.office_notification_id,'load_order_id',n.load_order_id,'type',n.notification_type,'title',n.title,'body',n.body,'payload',n.payload,'created_at',n.created_at,'read_at',n.read_at) order by n.created_at desc) from public.office_notifications n where n.office_id=v_office.office_id),'[]'::jsonb)
 );
end;
$function$;
revoke all on function public.branch_get_snapshot() from public,anon;
grant execute on function public.branch_get_snapshot() to authenticated;
notify pgrst,'reload schema';
